index 000000000..9bd72dec3
--- /dev/null
+++ b/ta4j-core/src/main/java/org/ta4j/core/portfolio/PortfolioAllocation.java
@@ -0,0 +1,214 @@
+/*
+ * SPDX-License-Identifier: MIT
+ */
+package org.ta4j.core.portfolio;
+
+import java.util.ArrayList;
+import java.util.Collections;
+import java.util.LinkedHashMap;
+import java.util.List;
+import java.util.Map;
+import java.util.Objects;
+
+import org.ta4j.core.analysis.WeightedValue;
+import org.ta4j.core.num.DecimalNumFactory;
+import org.ta4j.core.num.Num;
+import org.ta4j.core.num.NumFactory;
+
+/**
+ * Long-only static target weights for a portfolio backtest.
+ *
+ * <p>
+ * Weights are fractions of total portfolio value ({@code 0.6} means 60%). They
+ * may sum to less than {@code 1}; the remainder is the cash target. Sums
+ * greater than {@code 1} are rejected to keep execution unlevered. Assets of
+ * the {@link PortfolioSeries} that are missing from the allocation have a zero
+ * target and are sold on the first rebalance.
+ * </p>
+ *
+ * <p>
+ * An allocation is plain target data and does not choose a numeric
+ * representation: weights are stored exactly as {@code DecimalNum}, and
+ * {@link PortfolioSeriesManager} converts them to the {@link PortfolioSeries}'
+ * numeric factory when it runs. {@code Num} weights can be passed as
+ * {@code num.bigDecimalValue()} or through {@link #PortfolioAllocation(List)}.
+ * </p>
+ *
+ * <pre>{@code
+ * PortfolioAllocation sixtyForty = new PortfolioAllocation(Map.of("SPY", 0.6, "TLT", 0.4));
+ * PortfolioAllocation equityAndCash = new PortfolioAllocation(Map.of("SPY", 0.6)); // 40% cash
+ * }</pre>
+ *
+ * @since 0.25.1
+ */
+public final class PortfolioAllocation {
+
+    private static final NumFactory NUM_FACTORY = DecimalNumFactory.getInstance();
+
+    private final Map<String, Num> targetWeights;
+    private final Num totalWeight;
+    private final Num zero;
+    private final Num one;
+
+    /**
+     * Creates an allocation from literal target weights, for example
+     * {@code Map.of("SPY", 0.6, "TLT", 0.3)}.
+     *
+     * <p>
+     * Values are converted exactly through their decimal representation; the
+     * portfolio run converts them to the portfolio's numeric factory.
+     * </p>
+     *
+     * @param targetWeights target weights keyed by asset name; iteration order is
+     *                      retained
+     * @since 0.25.1
+     */
+    public PortfolioAllocation(Map<String, ? extends Number> targetWeights) {
+        this(numWeights(targetWeights));
+    }
+
+    /**
+     * Creates a fully invested allocation by normalizing relative weights so they
+     * sum to exactly {@code 1}.
+     *
+     * @param weightedAssets relative asset weights; repeated assets are summed
+     * @since 0.25.1
+     */
+    public PortfolioAllocation(List<WeightedValue<String>> weightedAssets) {
+        this(normalizedTargetWeights(weightedAssets));
+    }
+
+    private PortfolioAllocation(LinkedHashMap<String, Num> targetWeights) {
+        if (targetWeights.isEmpty()) {
+            throw new IllegalArgumentException("targetWeights must not be empty");
+        }
+
+        Map<String, Num> normalizedWeights = new LinkedHashMap<>();
+        Num normalizedTotalWeight = NUM_FACTORY.zero();
+        for (Map.Entry<String, Num> entry : targetWeights.entrySet()) {
+            String asset = requireAsset(entry.getKey());
+            Num weight = normalizeWeight(asset, entry.getValue());
+            normalizedWeights.put(asset, weight);
+            normalizedTotalWeight = normalizedTotalWeight.plus(weight);
+        }
+
+        Num unitWeight = NUM_FACTORY.one();
+        if (normalizedTotalWeight.isGreaterThan(unitWeight.plus(NUM_FACTORY.epsilon()))) {
+            throw new IllegalArgumentException("sum of target weights must be <= 1 but was " + normalizedTotalWeight);
+        }
+        if (normalizedTotalWeight.isGreaterThan(unitWeight)) {
+            // Absorb representation noise such as 0.1 + 0.2 + 0.7 in double math.
+            for (Map.Entry<String, Num> entry : normalizedWeights.entrySet()) {
+                entry.setValue(entry.getValue().dividedBy(normalizedTotalWeight));
+            }
+            normalizedTotalWeight = unitWeight;
+        }
+
+        this.targetWeights = Collections.unmodifiableMap(normalizedWeights);
+        this.totalWeight = normalizedTotalWeight;
+        this.zero = NUM_FACTORY.zero();
+        this.one = unitWeight;
+    }
+
+    /**
+     * @return target weights in allocation order
+     * @since 0.25.1
+     */
+    public Map<String, Num> getTargetWeights() {
+        return targetWeights;
+    }
+
+    /**
+     * Returns the target weight for an asset, or zero when it is intentionally
+     * unallocated.
+     *
+     * @param asset asset name
+     * @return target weight as a fraction of portfolio value
+     * @since 0.25.1
+     */
+    public Num getTargetWeight(String asset) {
+        return targetWeights.getOrDefault(requireAsset(asset), zero);
+    }
+
+    /**
+     * @return sum of all asset target weights
+     * @since 0.25.1
+     */
+    public Num getTotalWeight() {
+        return totalWeight;
+    }
+
+    /**
+     * @return cash target weight ({@code 1 - totalWeight})
+     * @since 0.25.1
+     */
+    public Num getCashWeight() {
+        return one.minus(totalWeight);
+    }
+
+    /**
+     * @return compact description with every target weight and the cash weight
+     */
+    @Override
+    public String toString() {
+        StringBuilder text = new StringBuilder("PortfolioAllocation{");
+        for (Map.Entry<String, Num> entry : targetWeights.entrySet()) {
+            text.append(entry.getKey()).append('=').append(entry.getValue()).append(", ");
+        }
+        return text.append("cash=").append(getCashWeight()).append('}').toString();
+    }
+
+    private static LinkedHashMap<String, Num> numWeights(Map<String, ? extends Number> targetWeights) {
+        Objects.requireNonNull(targetWeights, "targetWeights");
+        LinkedHashMap<String, Num> weights = new LinkedHashMap<>();
+        for (Map.Entry<String, ? extends Number> entry : targetWeights.entrySet()) {
+            String asset = requireAsset(entry.getKey());
+            Number weight = Objects.requireNonNull(entry.getValue(), "weight for " + asset);
+            try {
+                // Decimal conversion keeps finite values beyond the double range exact.
+                weights.put(asset, NUM_FACTORY.numOf(weight));
+            } catch (NumberFormatException exception) {
+                throw new IllegalArgumentException("target weight must be finite for asset " + asset, exception);
+            }
+        }
+        return weights;
+    }
+
+    private static LinkedHashMap<String, Num> normalizedTargetWeights(List<WeightedValue<String>> weightedAssets) {
+        Objects.requireNonNull(weightedAssets, "weightedAssets");
+        if (weightedAssets.isEmpty()) {
+            throw new IllegalArgumentException("weightedAssets must not be empty");
+        }
+
+        List<WeightedValue<String>> validatedWeights = new ArrayList<>(weightedAssets.size());
+        for (WeightedValue<String> weightedAsset : weightedAssets) {
+            Objects.requireNonNull(weightedAsset, "weightedAssets must not contain null entries");
+            String asset = requireAsset(weightedAsset.value());
+            validatedWeights.add(new WeightedValue<>(asset, normalizeWeight(asset, weightedAsset.weight())));
+        }
+        LinkedHashMap<String, Num> normalizedWeights = new LinkedHashMap<>();
+        for (WeightedValue<String> weightedAsset : WeightedValue.normalizeWeights(validatedWeights, NUM_FACTORY)) {
+            normalizedWeights.merge(weightedAsset.value(), weightedAsset.weight(), Num::plus);
+        }
+        return normalizedWeights;
+    }
+
+    private static String requireAsset(String asset) {
+        Objects.requireNonNull(asset, "asset");
+        if (asset.isBlank()) {
+            throw new IllegalArgumentException("asset must not be blank");
+        }
+        return asset;
+    }
+
+    private static Num normalizeWeight(String asset, Num weight) {
+        Objects.requireNonNull(weight, "weight for " + asset);
+        if (!Num.isFinite(weight)) {
+            throw new IllegalArgumentException("target weight must be finite for asset " + asset);
+        }
+        if (weight.isNegative()) {
+            throw new IllegalArgumentException("target weight must be >= 0 for asset " + asset);
+        }
+        return NUM_FACTORY.numOf(weight.bigDecimalValue());
+    }
+}
diff --git a/ta4j-core/src/main/java/org/ta4j/core/portfolio/PortfolioExecutionResult.java b/ta4j-core/src/main/java/org/ta4j/core/portfolio/PortfolioExecutionResult.java
new file mode 100644
index 000000000..c554c3161
--- /dev/null
+++ b/ta4j-core/src/main/java/org/ta4j/core/portfolio/PortfolioExecutionResult.java
@@ -0,0 +1,272 @@
+/*
+ * SPDX-License-Identifier: MIT
+ */
+package org.ta4j.core.portfolio;
+
+import java.math.MathContext;
+import java.time.Duration;
+import java.time.Instant;
+import java.util.EnumMap;
+import java.util.List;
+import java.util.Map;
+import java.util.Objects;
+
+import org.ta4j.core.BarSeries;
+import org.ta4j.core.BaseBarSeriesBuilder;
+import org.ta4j.core.num.Num;
+import org.ta4j.core.portfolio.PortfolioSnapshot.RebalanceStatus;
+
+/**
+ * Immutable result of a static target-weight portfolio run.
+ *
+ * <p>
+ * {@link #toString()} gives a compact summary (date range, value, return,
+ * costs, rebalance outcomes); the full per-bar history is available through
+ * {@link #getSnapshots()}. Returns are fractions ({@code 0.05} means 5%).
+ * </p>
+ *
+ * @since 0.25.1
+ */
+public final class PortfolioExecutionResult {
+
+    private static final MathContext SUMMARY_PRECISION = new MathContext(6);
+
+    private final PortfolioSeries series;
+    private final PortfolioAllocation allocation;
+    private final Num initialCash;
+    private final List<PortfolioSnapshot> snapshots;
+    private final Num totalTransactionCost;
+    private final Num totalTradedNotional;
+    private final Num totalTurnover;
+    private final Map<RebalanceStatus, Integer> rebalanceCounts;
+
+    PortfolioExecutionResult(PortfolioSeries series, PortfolioAllocation allocation, Num initialCash,
+            List<PortfolioSnapshot> snapshots) {
+        this.series = Objects.requireNonNull(series, "series");
+        this.allocation = Objects.requireNonNull(allocation, "allocation");
+        this.initialCash = Objects.requireNonNull(initialCash, "initialCash");
+        this.snapshots = List.copyOf(snapshots);
+        if (this.snapshots.isEmpty()) {
+            throw new IllegalArgumentException("snapshots must not be empty");
+        }
+        Num zero = initialCash.getNumFactory().zero();
+        Num costs = zero;
+        Num traded = zero;
+        Num turnover = zero;
+        Map<RebalanceStatus, Integer> counts = new EnumMap<>(RebalanceStatus.class);
+        for (RebalanceStatus status : RebalanceStatus.values()) {
+            counts.put(status, 0);
+        }
+        for (PortfolioSnapshot snapshot : this.snapshots) {
+            costs = costs.plus(snapshot.getTransactionCost());
+            traded = traded.plus(snapshot.getTradedNotional());
+            turnover = turnover.plus(snapshot.getTurnover());
+            counts.merge(snapshot.getRebalanceStatus(), 1, Integer::sum);
+        }
+        this.totalTransactionCost = costs;
+        this.totalTradedNotional = traded;
+        this.totalTurnover = turnover;
+        this.rebalanceCounts = counts;
+    }
+
+    /**
+     * @return aligned portfolio series the run used
+     * @since 0.25.1
+     */
+    public PortfolioSeries getPortfolioSeries() {
+        return series;
+    }
+
+    /**
+     * @return target allocation the run traded toward
+     * @since 0.25.1
+     */
+    public PortfolioAllocation getAllocation() {
+        return allocation;
+    }
+
+    /**
+     * @return starting cash in the portfolio numeric factory
+     * @since 0.25.1
+     */
+    public Num getInitialCash() {
+        return initialCash;
+    }
+
+    /**
+     * @return one immutable snapshot per aligned bar, in chronological order
+     * @since 0.25.1
+     */
+    public List<PortfolioSnapshot> getSnapshots() {
+        return snapshots;
+    }
+
+    /**
+     * Returns the snapshots whose rebalance ended with {@code status}, for example
+     * {@code getSnapshots(RebalanceStatus.PARTIAL)} to audit rebalances that could
+     * not restore the targets.
+     *
+     * @param status rebalance status to select
+     * @return matching snapshots in chronological order
+     * @since 0.25.1
+     */
+    public List<PortfolioSnapshot> getSnapshots(RebalanceStatus status) {
+        Objects.requireNonNull(status, "status");
+        return snapshots.stream().filter(snapshot -> snapshot.getRebalanceStatus() == status).toList();
+    }
+
+    /**
+     * @return final portfolio snapshot
+     * @since 0.25.1
+     */
+    public PortfolioSnapshot getFinalSnapshot() {
+        return snapshots.getLast();
+    }
+
+    /**
+     * @return final portfolio value
+     * @since 0.25.1
+     */
+    public Num getFinalValue() {
+        return getFinalSnapshot().getPortfolioValue();
+    }
+
+    /**
+     * @return fractional return from the initial cash to the final value, net of
+     *         all transaction costs including the initial investment's
+     * @since 0.25.1
+     */
+    public Num getTotalReturn() {
+        return getFinalValue().minus(initialCash).dividedBy(initialCash);
+    }
+
+    /**
+     * @return cumulative transaction costs
+     * @since 0.25.1
+     */
+    public Num getTotalTransactionCost() {
+        return totalTransactionCost;
+    }
+
+    /**
+     * @return cumulative gross notional traded (buys plus sells, excluding costs),
+     *         in currency units
+     * @since 0.25.1
+     */
+    public Num getTotalTradedNotional() {
+        return totalTradedNotional;
+    }
+
+    /**
+     * @return sum of every snapshot's {@link PortfolioSnapshot#getTurnover()
+     *         turnover ratio}
+     * @since 0.25.1
+     */
+    public Num getTotalTurnover() {
+        return totalTurnover;
+    }
+
+    /**
+     * @param status rebalance status to count
+     * @return number of bars that ended with {@code status}
+     * @since 0.25.1
+     */
+    public int getRebalanceCount(RebalanceStatus status) {
+        return rebalanceCounts.get(Objects.requireNonNull(status, "status"));
+    }
+
+    /**
+     * @return achieved asset weights at the final bar, in portfolio order
+     * @since 0.25.1
+     */
+    public Map<String, Num> getFinalWeights() {
+        return getFinalSnapshot().getAssetWeights();
+    }
+
+    /**
+     * Converts the run into a portfolio value (equity) series for existing ta4j
+     * indicators and criteria, for example
+     * {@code new EnterAndHoldCriterion(new NetReturnCriterion())} or
+     * {@code new EnterAndHoldCriterion(new MaximumDrawdownCriterion())}.
+     *
+     * <p>
+     * The series has one more bar than {@link #getSnapshots()}: bar {@code 0} is
+     * the initial-capital observation, ending at the begin time of the first
+     * aligned bar, so the initial investment's transaction costs are visible to
+     * return and drawdown analysis. Bar {@code i + 1} holds snapshot {@code i}.
+     * OHLC prices all equal the portfolio value and volume is zero.
+     * </p>
+     *
+     * @param name series name
+     * @return portfolio value series
+     * @since 0.25.1
+     */
+    public BarSeries toPortfolioValueSeries(String name) {
+        BarSeries valueSeries = new BaseBarSeriesBuilder().withName(name)
+                .withNumFactory(initialCash.getNumFactory())
+                .build();
+        Duration firstPeriod = series.timePeriod(0);
+        addValueBar(valueSeries, firstPeriod, series.getEndTimes().getFirst().minus(firstPeriod), initialCash);
+        for (PortfolioSnapshot snapshot : snapshots) {
+            addValueBar(valueSeries, series.timePeriod(snapshot.getIndex()), snapshot.getEndTime(),
+                    snapshot.getPortfolioValue());
+        }
+        return valueSeries;
+    }
+
+    /**
+     * Same as {@link #toPortfolioValueSeries(String)} with the name
+     * {@code "Portfolio value"}.
+     *
+     * @return portfolio value series
+     * @since 0.25.1
+     */
+    public BarSeries toPortfolioValueSeries() {
+        return toPortfolioValueSeries("Portfolio value");
+    }
+
+    /**
+     * @return compact summary: aligned date range, initial and final value, total
+     *         return, costs, traded notional, rebalance outcomes, and final weights
+     */
+    @Override
+    public String toString() {
+        StringBuilder weights = new StringBuilder("{");
+        for (Map.Entry<String, Num> entry : getFinalWeights().entrySet()) {
+            weights.append(entry.getKey()).append('=').append(brief(entry.getValue())).append(", ");
+        }
+        weights.append("cash=").append(brief(getFinalSnapshot().getCashWeight())).append('}');
+        Num totalReturn = getTotalReturn();
+        return "PortfolioExecutionResult{bars=" + snapshots.size() + ", from=" + series.getEndTimes().getFirst()
+                + ", to=" + series.getEndTimes().getLast() + ", initialCash=" + brief(initialCash) + ", finalValue="
+                + brief(getFinalValue()) + ", totalReturn=" + brief(totalReturn) + " ("
+                + brief(totalReturn.multipliedBy(totalReturn.getNumFactory().hundred())) + "%), transactionCost="
+                + brief(totalTransactionCost) + ", tradedNotional=" + brief(totalTradedNotional) + ", rebalances="
+                + rebalanceSummary() + ", finalWeights=" + weights + '}';
+    }
+
+    private String rebalanceSummary() {
+        return "{completed=" + rebalanceCounts.get(RebalanceStatus.COMPLETED) + ", partial="
+                + rebalanceCounts.get(RebalanceStatus.PARTIAL) + ", skipped="
+                + rebalanceCounts.get(RebalanceStatus.SKIPPED) + '}';
+    }
+
+    private static String brief(Num value) {
+        if (!Num.isFinite(value)) {
+            return value.toString();
+        }
+        return value.bigDecimalValue().round(SUMMARY_PRECISION).stripTrailingZeros().toPlainString();
+    }
+
+    private static void addValueBar(BarSeries valueSeries, Duration timePeriod, Instant endTime, Num value) {
+        valueSeries.barBuilder()
+                .timePeriod(timePeriod)
+                .endTime(endTime)
+                .openPrice(value)
+                .highPrice(value)
+                .lowPrice(value)
+                .closePrice(value)
+                .volume(valueSeries.numFactory().zero())
+                .add();
+    }
+}
diff --git a/ta4j-core/src/main/java/org/ta4j/core/portfolio/PortfolioSeries.java b/ta4j-core/src/main/java/org/ta4j/core/portfolio/PortfolioSeries.java
new file mode 100644
index 000000000..a7ed7c736
--- /dev/null
+++ b/ta4j-core/src/main/java/org/ta4j/core/portfolio/PortfolioSeries.java
@@ -0,0 +1,352 @@
+/*
+ * SPDX-License-Identifier: MIT
+ */
+package org.ta4j.core.portfolio;
+
+import java.time.Duration;
+import java.time.Instant;
+import java.util.ArrayList;
+import java.util.Arrays;
+import java.util.HashMap;
+import java.util.LinkedHashMap;
+import java.util.List;
+import java.util.Map;
+import java.util.Objects;
+import java.util.TreeSet;
+
+import org.ta4j.core.Bar;
+import org.ta4j.core.BarSeries;
+import org.ta4j.core.BaseBar;
+import org.ta4j.core.BaseBarSeriesBuilder;
+import org.ta4j.core.num.NaN;
+import org.ta4j.core.num.Num;
+import org.ta4j.core.num.NumFactory;
+
+/**
+ * Immutable, chronologically aligned collection of named {@link BarSeries}
+ * instances: the input of a portfolio backtest.
+ *
+ * <p>
+ * Alignment is deterministic and strict: the portfolio timeline is the
+ * intersection of bar end times present in every source series. Missing bars
+ * are excluded instead of being forward-filled, so callers that need
+ * exchange-calendar joins or carry-forward bars should prepare those inputs
+ * upstream. All prices must be quoted in one common currency and include any
+ * split/dividend adjustments the experiment requires.
+ * </p>
+ *
+ * <p>
+ * The portfolio owns a detached copy of every source bar, taken once during
+ * construction. Later mutations of the source series or of their bars (for
+ * example {@link BarSeries#addPrice(Num)}) do not change the portfolio, and the
+ * bars and series returned by {@link #getBar(String, int)} and
+ * {@link #getBarSeries(String)} are fresh copies that callers may modify
+ * freely. Repeated backtests over the same instance are therefore reproducible.
+ * </p>
+ *
+ * <p>
+ * A single series is a valid portfolio (for example a 60% equity / 40% cash
+ * benchmark). The simple constructors use each {@link BarSeries#getName()} as
+ * its asset name; use {@link #PortfolioSeries(Map)} for explicit aliases.
+ * Portfolio-level accounting uses the {@link NumFactory} of the first series.
+ * </p>
+ *
+ * @since 0.25.1
+ */
+public final class PortfolioSeries {
+
+    private final List<String> assets;
+    private final Map<String, Integer> assetPositions;
+    private final BarSeries[] ownedSeries;
+    private final List<Instant> endTimes;
+    private final int[][] sourceIndexes;
+    private final Num[][] closePrices;
+    private final NumFactory numFactory;
+
+    /**
+     * Creates a portfolio from bar series, using each series name as its asset
+     * name.
+     *
+     * @param series non-empty source bar series in portfolio order
+     * @since 0.25.1
+     */
+    public PortfolioSeries(BarSeries... series) {
+        this(Arrays.asList(Objects.requireNonNull(series, "series")));
+    }
+
+    /**
+     * Creates a portfolio from bar series, using each series name as its asset
+     * name.
+     *
+     * @param series non-empty source bar series in portfolio order
+     * @since 0.25.1
+     */
+    public PortfolioSeries(List<BarSeries> series) {
+        this(seriesByName(series));
+    }
+
+    /**
+     * Creates a portfolio from explicit asset-name and bar-series associations.
+     *
+     * <p>
+     * Encounter order is retained for snapshots, weights, and normal iteration, so
+     * prefer an ordered map such as {@link LinkedHashMap}.
+     * </p>
+     *
+     * @param seriesByAsset non-empty source series keyed by non-blank asset name
+     * @since 0.25.1
+     */
+    public PortfolioSeries(Map<String, BarSeries> seriesByAsset) {
+        Objects.requireNonNull(seriesByAsset, "seriesByAsset");
+        if (seriesByAsset.isEmpty()) {
+            throw new IllegalArgumentException("portfolio series must contain at least one asset");
+        }
+
+        List<String> assetNames = new ArrayList<>(seriesByAsset.size());
+        Map<String, Integer> positions = new HashMap<>();
+        BarSeries[] owned = new BarSeries[seriesByAsset.size()];
+        for (Map.Entry<String, BarSeries> entry : seriesByAsset.entrySet()) {
+            String asset = requireAssetName(entry.getKey());
+            BarSeries source = Objects.requireNonNull(entry.getValue(), "series must not be null for asset " + asset);
+            if (source.isEmpty()) {
+                throw new IllegalArgumentException("series must not be empty for asset " + asset);
+            }
+            if (positions.putIfAbsent(asset, assetNames.size()) != null) {
+                throw new IllegalArgumentException("duplicate portfolio asset: " + asset);
+            }
+            owned[assetNames.size()] = detachedCopy(source);
+            assetNames.add(asset);
+        }
+
+        this.assets = List.copyOf(assetNames);
+        this.assetPositions = Map.copyOf(positions);
+        this.ownedSeries = owned;
+        this.numFactory = owned[0].numFactory();
+
+        List<Map<Instant, Integer>> indexesByEndTime = new ArrayList<>(owned.length);
+        for (int position = 0; position < owned.length; position++) {
+            indexesByEndTime.add(indexesByEndTime(assets.get(position), owned[position]));
+        }
+        TreeSet<Instant> commonEndTimes = new TreeSet<>(indexesByEndTime.getFirst().keySet());
+        for (Map<Instant, Integer> currentIndexes : indexesByEndTime) {
+            commonEndTimes.retainAll(currentIndexes.keySet());
+        }
+        if (commonEndTimes.isEmpty()) {
+            throw new IllegalArgumentException("portfolio series do not share any common bar end times");
+        }
+
+        this.endTimes = List.copyOf(commonEndTimes);
+        this.sourceIndexes = new int[owned.length][endTimes.size()];
+        this.closePrices = new Num[owned.length][endTimes.size()];
+        for (int position = 0; position < owned.length; position++) {
+            Map<Instant, Integer> currentIndexes = indexesByEndTime.get(position);
+            for (int index = 0; index < endTimes.size(); index++) {
+                int sourceIndex = currentIndexes.get(endTimes.get(index));
+                sourceIndexes[position][index] = sourceIndex;
+                closePrices[position][index] = toPortfolioNum(owned[position].getBar(sourceIndex).getClosePrice());
+            }
+        }
