+                + ", to=" + endTimes.getLast() + '}';
+    }
+
+    Num closePrice(int assetPosition, int index) {
+        return closePrices[assetPosition][index];
+    }
+
+    Duration timePeriod(int index) {
+        return ownedSeries[0].getBar(sourceIndexes[0][index]).getTimePeriod();
+    }
+
